from taf.cloud.cbam.catalog.v18.catalog import Catalog18
from taf.cloud.cbam.session import CbamSession
from taf.cloud.cbam.session import CbamResponse
from test import unittest, Mock


class TestCatalog(unittest.TestCase):
    def setUp(self):
        self.m_client = Mock(spec=CbamSession)
        self.catalog = Catalog18(self.m_client)

    def test_getCatalogInfo_returnRightParams(self):
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value={'title': 'abc'}), status_code=200))

        resp = self.catalog.get_info()
        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='get', endpoint='api/catalog/adapter/vnfpackages')
        self.assertEqual(resp, {'title': 'abc'})

    def test_postCatalogInfo_returnRightParams(self):
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value={'title': 'abc'}), status_code=200))
        file_mock = Mock(autospec=True)

        resp = self.catalog.post_info(file_mock)

        self.m_client.send_request.assert_called_with(
            api_version=None,
            content_type=None, files={'content': file_mock},
            endpoint='api/catalog/adapter/vnfpackages', method='post')
        self.assertEqual(resp, {'title': 'abc'})

    def test_deleteCatalogInfo_returnRightParams(self):
        self.m_client.send_request.return_value = CbamResponse(
            Mock(json=Mock(return_value={'title': 'abc'}), status_code=200))

        resp = self.catalog.delete_info('vnfd_id')

        self.m_client.send_request.assert_called_with(
            api_version=None,
            method='delete',
            endpoint='api/catalog/adapter/vnfpackages/vnfd_id')
        self.assertDictEqual(resp, {'title': 'abc'})
